export const getPoliciesViewUrl = (policyKey: string,
    params?: PoliciesViewParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/policies/${policyKey}/?${stringifiedParams}` : `/api/v1/policies/${policyKey}/`
}

/**
 * @summary View
 */
export const policiesView = async (policyKey: string,
    params?: PoliciesViewParams, options?: Parameters<typeof compassFetch>[1]): Promise<policiesViewResponse> => {

  return compassFetch<policiesViewResponse>(getPoliciesViewUrl(policyKey,params),
  {
    ...options,
    method: 'GET'


  }
);}
